<?php
session_start();require __DIR__.'/app/config/db_connection.php';if(!isset($_SESSION['admin_id'])){header('Location:admin_login.php');exit;}if(empty($_SESSION['admin_users_csrf']))$_SESSION['admin_users_csrf']=bin2hex(random_bytes(32));$message='';$error='';
function logAdminUserChange($c,$id,$text){$s=$c->prepare('INSERT INTO admin_audit_log(admin_id,action_text) VALUES(?,?)');$s->bind_param('is',$id,$text);$s->execute();$s->close();}
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['type']??'';$id=(int)($_POST['id']??0);$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$contact=trim($_POST['contact']??'');if(!hash_equals($_SESSION['admin_users_csrf'],$_POST['csrf_token']??''))$error='Your session expired. Refresh and try again.';elseif(!in_array($type,['student','seller'],true)||!$id||$name==='')$error='Enter complete account details.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';elseif($type==='student'){$school=trim($_POST['student_id']??'');if($school==='')$error='School ID is required.';else{$s=$conn->prepare('UPDATE students SET full_name=?,email=?,contact=?,student_id=? WHERE id=?');$s->bind_param('ssssi',$name,$email,$contact,$school,$id);if($s->execute()){$message='Student account updated.';logAdminUserChange($conn,$_SESSION['admin_id'],"Updated student account #$id");}else $error='Unable to update this student. The email or School ID may already be in use.';$s->close();}}else{$status=$_POST['approval_status']??'pending';if(!in_array($status,['pending','approved','rejected','suspended'],true))$error='Invalid seller access status.';else{$s=$conn->prepare('UPDATE sellers SET full_name=?,email=?,contact=?,approval_status=? WHERE id=?');$s->bind_param('ssssi',$name,$email,$contact,$status,$id);if($s->execute()){$message='Seller account updated.';logAdminUserChange($conn,$_SESSION['admin_id'],"Updated seller account #$id");}else $error='Unable to update this seller. The email may already be in use.';$s->close();}}}
$students=$conn->query('SELECT id,full_name,student_id,email,contact FROM students ORDER BY full_name');$sellers=$conn->query('SELECT id,full_name,email,contact,approval_status FROM sellers ORDER BY full_name');
?>
<style>body{display:flex!important;flex-direction:column!important}.top{order:0}.notice{order:1}.tabs{order:2}.search{order:3}.panel{order:4}</style>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User Management | UniCanteen</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@400;600&display=swap" rel="stylesheet"><style>:root{--blue:#2563eb;--muted:#64748b}*{box-sizing:border-box}body{margin:0;padding:24px;font:14px Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.top,.card,.modal-box{background:#fff;border-radius:12px;box-shadow:0 2px 10px #0000000d}.top{padding:18px 22px;margin-bottom:18px}.top h1,.modal-box h2{font:700 21px Montserrat;margin:0}.top p{margin:5px 0 0;color:var(--muted);font-size:13px}.support{float:right;background:#eef2ff;color:#1d4ed8;text-decoration:none;padding:8px 11px;border-radius:7px;font-size:12px;font-weight:600}.tabs{display:flex;gap:8px;margin-bottom:12px}.tabs button{border:0;border-radius:8px;padding:9px 14px;background:#e2e8f0;font-weight:600;cursor:pointer}.tabs button.active{background:var(--blue);color:#fff}.search{width:min(420px,100%);margin:0 0 12px;padding:11px 13px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.panel{display:none}.panel.active{display:block}.card{padding:18px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #e2e8f0;font-size:13px}th{color:var(--muted);font-size:12px}.status{padding:4px 8px;border-radius:20px;background:#e2e8f0;text-transform:capitalize;font-size:12px}.edit,.save,.cancel{border:0;border-radius:7px;padding:8px 12px;font-weight:600;cursor:pointer}.edit,.save{background:var(--blue);color:#fff}.notice{padding:10px 14px;border-radius:8px;margin-bottom:14px}.ok{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#b91c1c}.modal{position:fixed;inset:0;background:#0007;display:none;align-items:center;justify-content:center;z-index:5}.modal.open{display:flex}.modal-box{width:min(460px,calc(100% - 30px));padding:22px}.modal-box h2{font-size:19px;margin-bottom:12px}.modal label{display:block;font-size:12px;font-weight:600;margin-top:10px}.modal input,.modal select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;margin-top:4px;font:inherit}.actions{display:flex;gap:8px;margin-top:18px}.cancel{background:#e2e8f0}</style></head><body><section class="top"><a class="support" href="admin_account_support.php">Account Support / Password Reset</a><h1>User Management</h1><p>Search, review, and update accounts only when a user requests help.</p></section><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice error"><?=htmlspecialchars($error)?></div><?php endif?><input class="search" id="userSearch" placeholder="Search by name, School ID, email, or contact" aria-label="Search users"><div class="tabs"><button class="active" data-panel="students">Students</button><button data-panel="sellers">Sellers</button></div><section class="panel active" id="students"><div class="card"><table><thead><tr><th>Student</th><th>School ID</th><th>Email</th><th>Contact</th><th></th></tr></thead><tbody><?php while($u=$students->fetch_assoc()):?><tr class="user-row"><td><b><?=htmlspecialchars($u['full_name'])?></b></td><td><?=htmlspecialchars($u['student_id'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['contact'])?></td><td><button class="edit" data-type="student" data-id="<?=$u['id']?>" data-full-name="<?=htmlspecialchars($u['full_name'],ENT_QUOTES)?>" data-email="<?=htmlspecialchars($u['email'],ENT_QUOTES)?>" data-contact="<?=htmlspecialchars($u['contact'],ENT_QUOTES)?>" data-school="<?=htmlspecialchars($u['student_id'],ENT_QUOTES)?>">Edit</button></td></tr><?php endwhile?></tbody></table></div></section><section class="panel" id="sellers"><div class="card"><table><thead><tr><th>Seller</th><th>Email</th><th>Contact</th><th>Access</th><th></th></tr></thead><tbody><?php while($u=$sellers->fetch_assoc()):?><tr class="user-row"><td><b><?=htmlspecialchars($u['full_name'])?></b></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['contact'])?></td><td><span class="status"><?=htmlspecialchars($u['approval_status'])?></span></td><td><button class="edit" data-type="seller" data-id="<?=$u['id']?>" data-full-name="<?=htmlspecialchars($u['full_name'],ENT_QUOTES)?>" data-email="<?=htmlspecialchars($u['email'],ENT_QUOTES)?>" data-contact="<?=htmlspecialchars($u['contact'],ENT_QUOTES)?>" data-status="<?=htmlspecialchars($u['approval_status'],ENT_QUOTES)?>">Edit</button></td></tr><?php endwhile?></tbody></table></div></section><div class="modal" id="editModal"><form class="modal-box" method="post"><h2 id="modalTitle">Edit account</h2><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['admin_users_csrf'])?>"><input type="hidden" name="type" id="accountType"><input type="hidden" name="id" id="accountId"><label>Full name</label><input name="full_name" id="fullName" required><label>Email</label><input type="email" name="email" id="accountEmail" required><label>Contact</label><input name="contact" id="accountContact"><div id="studentFields"><label>School ID</label><input name="student_id" id="studentId"></div><div id="sellerFields"><label>Seller access</label><select name="approval_status" id="approvalStatus"><option>pending</option><option>approved</option><option>rejected</option><option>suspended</option></select></div><div class="actions"><button class="save">Save changes</button><button class="cancel" type="button" id="closeModal">Cancel</button></div></form></div><script>const modal=document.getElementById('editModal'),accountType=document.getElementById('accountType'),accountId=document.getElementById('accountId'),fullName=document.getElementById('fullName'),accountEmail=document.getElementById('accountEmail'),accountContact=document.getElementById('accountContact'),studentId=document.getElementById('studentId'),approvalStatus=document.getElementById('approvalStatus'),studentFields=document.getElementById('studentFields'),sellerFields=document.getElementById('sellerFields'),modalTitle=document.getElementById('modalTitle');document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tabs button').forEach(item=>item.classList.remove('active'));document.querySelectorAll('.panel').forEach(item=>item.classList.remove('active'));button.classList.add('active');document.getElementById(button.dataset.panel).classList.add('active')}));document.getElementById('userSearch').addEventListener('input',event=>{const query=event.target.value.toLowerCase().trim();document.querySelectorAll('.user-row').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(query)?'':'none')});document.querySelectorAll('.edit').forEach(button=>button.addEventListener('click',()=>{const seller=button.dataset.type==='seller';accountType.value=button.dataset.type;accountId.value=button.dataset.id;fullName.value=button.dataset.fullName;accountEmail.value=button.dataset.email;accountContact.value=button.dataset.contact;studentId.value=button.dataset.school||'';approvalStatus.value=button.dataset.status||'pending';studentFields.style.display=seller?'none':'block';sellerFields.style.display=seller?'block':'none';modalTitle.textContent='Edit '+(seller?'seller':'student')+' account';modal.classList.add('open')}));document.getElementById('closeModal').addEventListener('click',()=>modal.classList.remove('open'));modal.addEventListener('click',event=>{if(event.target===modal)modal.classList.remove('open')});</script></body></html>
